type ErrorContext struct {state *errorContextState}
type errorContextState struct {client *Client;owner uint64;id atomic.Uint64}
func(value *ErrorContext) MarshalJSON()([]byte,error){if value==nil||value.state==nil||value.state.id.Load()==0{return nil,ErrClosed};return json.Marshal(map[string]uint64{"owner":value.state.owner,"id":value.state.id.Load()})}
func(value *ErrorContext) UnmarshalJSON(data []byte)error{var fields map[string]json.RawMessage;if err:=json.Unmarshal(data,&fields);err!=nil{return err};if len(fields)!=2{return fmt.Errorf("invalid error context reference")};var owner,id uint64;if err:=json.Unmarshal(fields["owner"],&owner);err!=nil{return err};if err:=json.Unmarshal(fields["id"],&id);err!=nil{return err};if owner==0||id==0{return fmt.Errorf("invalid error context identity")};state:=&errorContextState{owner:owner};state.id.Store(id);value.state=state;return nil}
func(value *ErrorContext) Close()error{if value==nil||value.state==nil{return nil};state:=value.state;client:=state.client;if client==nil{state.id.Store(0);return nil};client.mu.Lock();defer client.mu.Unlock();id:=state.id.Swap(0);runtime.SetFinalizer(state,nil);if id==0||client.handle==0{return nil};return client.closeContext(id)}
func(value *ErrorContext) IsClosed()bool{if value==nil||value.state==nil||value.state.id.Load()==0||value.state.client==nil{return true};client:=value.state.client;client.mu.Lock();defer client.mu.Unlock();return client.handle==0||value.state.id.Load()==0}
func bindContext(client *Client,value *ErrorContext)error{if value==nil||value.state==nil||value.state.id.Load()==0{return ErrClosed};state:=value.state;if state.client!=nil&&state.client!=client{return fmt.Errorf("error context belongs to another Component client")};if state.client==nil{state.client=client;runtime.SetFinalizer(state,func(state *errorContextState){value:=&ErrorContext{state:state};_=value.Close()})};return nil}
func validateContextArgument(client *Client,value *ErrorContext)error{if value==nil||value.state==nil||value.state.id.Load()==0{return ErrClosed};if value.state.client!=client{return fmt.Errorf("error context belongs to another Component client")};return nil}
